{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "CLR457, the closest analogue, showed a brain/plasma AUC ratio of 0.07, indicating minimal CNS penetration; its shared aminopyrimidine and morpholine pharmacophore with the query supports a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Compound 7b, a close analogue with an aminopyridine/morpholine-like fused core, gave minimal brain levels after oral dosing in rats, supporting poor CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The thienopyrimidine-morpholine PET tracer TOZ1 showed low brain uptake (SUV 0.4), directly relevant to the query's thienopyrimidine-morpholine scaffold and indicating limited BBB permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A moderately similar morpholinopyrimidine radiotracer achieved high initial brain SUV (2.8) and was judged brain penetrant, providing contradictory evidence that this chemotype can access the CNS.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "FMN3PA, a tert-butyl/morpholine-containing radiotracer, showed brain uptake with a brain/blood ratio of 0.5, providing contradictory evidence for possible CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-similarity direct CNS exposure measurements (brain/plasma AUC 0.07, minimal brain levels, low SUV) consistently indicate poor brain penetration for the query's aminopyrimidine/morpholine thienopyrimidine scaffold. Although some lower-similarity analogues are brain-penetrant, the transferable weight favors fail.",
  "evidence_gaps": [
    "No direct experimental PK or brain exposure data for the exact query molecule.",
    "Morgan similarities are moderate (0.23-0.30), limiting certainty of transfer.",
    "Conflicting brain-penetrant analogues at lower similarity suggest scaffold tolerance for CNS access is context-dependent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

